package com.factory.copilot.service; import com.factory.copilot.entity.Machine; import com.factory.copilot.entity.Incident; import com.factory.copilot.entity.MaintenanceRecord; import com.factory.copilot.entity.SensorReading; import com.factory.copilot.repository.MachineRepository; import com.factory.copilot.repository.IncidentRepository; import com.factory.copilot.repository.MaintenanceRecordRepository; import com.factory.copilot.repository.SensorReadingRepository; import org.springframework.stereotype.Service; import java.util.HashMap; import java.util.List; import java.util.Map; @Service public class CopilotService { private final MachineRepository machineRepository; private final IncidentRepository incidentRepository; private final MaintenanceRecordRepository maintenanceRepository; private final SensorReadingRepository sensorRepository; public CopilotService(MachineRepository machineRepository, IncidentRepository incidentRepository, MaintenanceRecordRepository maintenanceRepository, SensorReadingRepository sensorRepository) { this.machineRepository = machineRepository; this.incidentRepository = incidentRepository; this.maintenanceRepository = maintenanceRepository; this.sensorRepository = sensorRepository; } public Map<String,Object> getMachineContext(Long machineId) { Machine machine = machineRepository.findById(machineId).orElse(null); if (machine == null) { return Map.of("error", "Machine not found"); } List<Incident> incidents = incidentRepository.findByMachineId(machineId); List<MaintenanceRecord> maintenance = maintenanceRepository.findByMachineId(machineId); List<SensorReading> sensors = sensorRepository.findByMachineId(machineId); Map<String,Object> context = new HashMap<>(); context.put("machine", machine); context.put("incidents", incidents); context.put("maintenance", maintenance); context.put("sensorReadings", sensors); return context; } }
